#!/bin/bash
# Random init dataset of set C (8 elements without problematic ones: Ti Nb Zr Hf Ta Mo W Y), computed from scratch
# (2026-11-17; no points copied from sets A/B).  List slurm/compositions/TiNbZrHfTaMoWY_gl.csv, 1200 compositions:
# 600 full simplex (seeds 8000..8599; ~400 would give the same mean nearest-neighbour distance as 1000 points for
# 10 elements, increased to 600 on purpose) + 100 faces for every k = 7 ... 2 (seeds 100000 + 1000 k + i,
# fractions >= 0.05).  Generated by scripts/composition_list.py (see slurm/README.md).  Full pipeline in GL (gg +
# lloyd, consts.py), PBE, ew 0.6, bzqlty 10, same as the A/B databases.
# Default 36 tasks x <=34 interleaved rows, 6 concurrent (6 rounds of 8-component alloys): one wave under the
# 512-cpu cap if no other jobs hold cpus.
#   slurm/submit_random_gl_TiNbZrHfTaMoWY.sh
#   env DRYRUN=1 slurm/submit_random_gl_TiNbZrHfTaMoWY.sh                 plan only (tcsh: env VAR=x cmd)
#   env FILE=slurm/compositions/TiNbZrHfTaMoWY_gl.missing.csv NTASKS=10 slurm/submit_random_gl_TiNbZrHfTaMoWY.sh
FILE=${FILE:-slurm/compositions/TiNbZrHfTaMoWY_gl.csv}
WORKDIR=${WORKDIR:-random.ratios/sra.TiNbZrHfTaMoWY.kp10.ew0.6.gl}
NTASKS=${NTASKS:-36}; CONCURRENT=${CONCURRENT:-6}; JOBNAME=rnd8C
# run directly on the login node (it calls sbatch itself); under sbatch $0 is a spool copy without submit_complist.sh
[ -n "${SLURM_JOB_ID:-}" ] && { echo "this submit script calls sbatch itself: run it on the login node WITHOUT sbatch, e.g.  slurm/submit_random_gl_TiNbZrHfTaMoWY.sh"; exit 2; }
source "$(dirname "$0")/submit_complist.sh"
